file.specification:

// ZONE LAYOUT (flex-col, height: 100dvh, overflow: hidden):
//
// [TopBar]    44px  — zinc-900 bg
//   Left:  mode label (SOLO FREE / SOLO CASINO) font-mono font-bold text-amber-400
//   Center: Round # display
//   Right: gear button (U+2699 text, opens SettingsModal)
//
// [EnergyBar] 48px — EnergyMeter component (full width)
//   Receives energy, globalMode, isInstability, isCatchup from useEnergy
//
// [InfoStrip] 36px — zinc-950 bg, border-b border-zinc-800
//   Left:  multiplier badge "x1.5" in amber, font-mono font-black
//   Center: MultiplierLadder (6 dots, compact)
//   Right: last combo label (e.g. "THREE OF A KIND") text-xs font-mono
//
// [Grid]      flex-1 — position: relative, overflow: hidden
//   Grid component fills this zone
//   FrenzyOverlay absolutely positioned over grid (pointer-events: none)
//   Chain preview banner: absolutely positioned top of grid zone
//     Shows "THREE 1s + SINGLE 5 = 1050 x1.5" while dragging
//     Shows "FARKLE" in red when chain would score 0
//
// [BankBar]   68px — zinc-900 bg, border-t border-zinc-800
//   Left section:  "BANKED" label + value in green (permanent)
//   Center section: "AT RISK" label + value in amber (pulsing when > 0)
//   Right section: [BANK] button — amber bg, text-black, font-black
//                  Disabled and grayed when unbanked === 0
//                  Shows rewarded ad option: small "Watch ad +50 FD" text below button
//                  Only shown when adsEnabled and rewarded ad available
//
// ROUND_END interstitial:
//   When roundPhase === 'ROUND_END' and interstitialDue === true:
//   Show full-screen overlay with "Round Complete" + score summary
//   "Watch Ad for Bonus FD" button (calls onInterstitialRequest prop)
//   "Continue" button skips ad
//   5-second auto-continue if no interaction
//
// ResizeObserver on Grid container ref:
//   On resize: cellSize = Math.floor((Math.min(w, h) - 16) / gridDim)
//   Clamp: Math.max(28, Math.min(72, cellSize))
//   Pass cellSize down to Grid component as prop
//
// SettingsModal: rendered at root of GameScreen, isOpen state managed here
// ScorePopup: absolutely positioned, rendered via portal or absolute in Grid zone
//
// Props:
//   mode: GameMode
//   adsEnabled?: boolean
//   onRewardedAdRequest?: () => void
//   onInterstitialRequest?: () => void
